create table if not exists public.schoolpro_admission_documents(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.schoolpro_admissions(id) on delete cascade,document_type text not null,file_url text not null,verified boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.schoolpro_admission_events(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.schoolpro_admissions(id) on delete cascade,event_type text not null,scheduled_at timestamptz,location text,notes text,status text not null default 'scheduled',created_at timestamptz not null default now());
create table if not exists public.schoolpro_admission_offers(id uuid primary key default gen_random_uuid(),application_id uuid not null unique references public.schoolpro_admissions(id) on delete cascade,offer_number text not null,offered_class text,letter_body text,issued_at timestamptz not null default now(),expires_at timestamptz,accepted_at timestamptz,status text not null default 'offered');
create table if not exists public.schoolpro_email_queue(id uuid primary key default gen_random_uuid(),school_id uuid references public.schoolpro_schools(id) on delete cascade,recipient_email text not null,recipient_name text,template_key text not null,subject text not null,payload jsonb not null default '{}'::jsonb,status text not null default 'pending',scheduled_at timestamptz not null default now(),sent_at timestamptz,error text,created_at timestamptz not null default now());
alter table public.schoolpro_admissions add column if not exists entrance_test_id uuid references public.schoolpro_cbt_tests(id),add column if not exists entrance_score numeric,add column if not exists acceptance_fee_status text not null default 'not_required';
alter table public.schoolpro_admission_documents enable row level security;alter table public.schoolpro_admission_events enable row level security;alter table public.schoolpro_admission_offers enable row level security;alter table public.schoolpro_email_queue enable row level security;
grant select,insert,update,delete on public.schoolpro_admission_documents,public.schoolpro_admission_events,public.schoolpro_admission_offers to authenticated;grant select on public.schoolpro_email_queue to authenticated;
create or replace function public.queue_schoolpro_email(p_school uuid,p_email text,p_name text,p_template text,p_subject text,p_payload jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare eid uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid()) and not exists(select 1 from public.schoolpro_schools s where s.id=p_school and s.owner_id=auth.uid()) then raise exception 'Not authorized';end if;if p_email is null or position('@' in p_email)=0 then raise exception 'Valid email required';end if;insert into public.schoolpro_email_queue(school_id,recipient_email,recipient_name,template_key,subject,payload)values(p_school,lower(trim(p_email)),p_name,p_template,p_subject,coalesce(p_payload,'{}'::jsonb))returning id into eid;return eid;end$$;revoke all on function public.queue_schoolpro_email(uuid,text,text,text,text,jsonb) from public,anon;grant execute on function public.queue_schoolpro_email(uuid,text,text,text,text,jsonb) to authenticated;